Rules.InvariantScript:
UpdateContext(
    {
        var_idModulo: LookUp(
            col_menuModulos,
            Titulo = var_tituloModulo,
            ID
        ),
        var_visibleMain: true,
        var_visibleExcluirTesteContato: false,
        var_dadosTesteContatos: Defaults(tbl_Checklist_REA_base)
    }
);

Set(varEmailFallbackNotificacao, "gilberto.claudino@motiva.com.br");

Select(ButtonRefreshChekREAcontatos);

Set(varTesteAtualID, Blank());
Set(varTesteSelecionado, Blank());
Set(varAeroportoTesteAtual, Blank());
Set(varAeroportoRelatorio, Blank());
Set(varConfirmando, false);
Set(varFinalizandoTeste, false);

/* Exclusão de teste */
Set(varExcluindoTesteContatos, false);
Set(varVisibleExcluirTesteContatos, false);
Set(varReativarContatosAoExcluirTeste, false);

ClearCollect(
    colTestesExecucao,
    FirstN(
        tbl_testeContatos,
        0
    )
);

ClearCollect(
    colTestesRelatorio,
    FirstN(
        tbl_testeContatos,
        0
    )
);

ClearCollect(
    colContatosDesatualizadosEmail,
    FirstN(
        tbl_contatos_entidades,
        0
    )
);

ClearCollect(
    colTesteContatosExcluir,
    FirstN(
        tbl_testeContatos,
        0
    )
);

ClearCollect(
    colContatosRollbackExcluir,
    FirstN(
        tbl_contatos_entidades,
        0
    )
)

If(
    IsBlank(cmbCKREAaeroporto_1.Selected.Result),

    Notify(
        "Selecione um aeroporto antes de iniciar o teste.",
        NotificationType.Warning,
        3000
    ),

    Set(
        varAeroSelecionado,
        cmbCKREAaeroporto_1.Selected.Result
    );

    Set(
        varIATATeste,
        Coalesce(
            LookUp(
                colAeros,
                Aeroporto = varAeroSelecionado,
                IATA
            ),
            varIATAUser,
            Left(
                varAeroSelecionado,
                3
            )
        )
    );

    Set(varConfirmando, false);
    Set(varFinalizandoTeste, false);
    Set(varAeroportoTesteAtual, varAeroSelecionado);

    Refresh(tbl_Checklist_REA_base);

    ClearCollect(
        colCheckListREA_Aeroporto,
        Sort(
            Filter(
                tbl_Checklist_REA_base,
                ID_modulo = var_idModulo &&
                Aeroporto = varAeroSelecionado
            ),
            ID,
            SortOrder.Descending
        )
    );

    If(
        !IsBlank(
            LookUp(
                colCheckListREA_Aeroporto,
                Status = "Em andamento",
                ID
            )
        ),

        Notify(
            "Já existe um Teste de Contatos de Emergência em andamento para este aeroporto. Continue ou finalize o teste existente antes de iniciar um novo.",
            NotificationType.Warning,
            5000
        ),

        Set(varNovoTesteContato, false);

        Set(
            varNovoTesteBase,
            Patch(
                tbl_Checklist_REA_base,
                Defaults(tbl_Checklist_REA_base),
                {
                    Aeroporto: varAeroSelecionado,
                    Data: Now(),
                    Bloco: If(
                        IsBlank(cmbCKREAbloco_1.Selected.Value),
                        varBlocoUser,
                        cmbCKREAbloco_1.Selected.Value
                    ),
                    ID_modulo: var_idModulo,
                    IATA: varIATATeste,
                    Status: "Em andamento"
                }
            )
        );

        Set(
            varTesteSelecionado,
            Patch(
                tbl_Checklist_REA_base,
                varNovoTesteBase,
                {
                    Protocolo: varIATATeste & "-TES-CONT-" & Text(varNovoTesteBase.ID)
                }
            )
        );

        Set(varTesteAtualID, varTesteSelecionado.ID);
        Set(varAeroportoTesteAtual, varTesteSelecionado.Aeroporto);

        ClearCollect(
            colContatosAero,
            Filter(
                tbl_contatos_entidades,
                status = "Atualizado" &&
                Aeroporto = varAeroportoTesteAtual
            )
        );

        ClearCollect(
            colTestesExecucao,
            Filter(
                tbl_testeContatos,
                id_teste_base = varTesteAtualID &&
                aeroporto = varAeroportoTesteAtual
            )
        );

        UpdateContext(
            {
                var_visibleNovoTeste: true,
                var_relatorio: false,
                var_dadosTesteContato: varTesteSelecionado
            }
        );

        EditForm(FormNovoTeste);

        Notify(
            "Teste iniciado com sucesso. Protocolo gerado: " & varTesteSelecionado.Protocolo,
            NotificationType.Success,
            4000
        );

        Select(ButtonRefreshChekREAcontatos)
    )
)

"Novo Teste"
/*If(
    !IsBlank(
        LookUp(
            col_checkListREA;
            Month(Data) = Month(Today()) && Year(Data) = Year(Today())
        )
    );"Teste Realizado"; "Novo Teste")*/

Refresh(tbl_Checklist_REA_base);
Refresh(tbl_testeContatos);
Refresh(tbl_contatos_entidades);
ClearCollect(
    col_checkListREA,
    Sort(
        Filter(
            tbl_Checklist_REA_base,
            ID_modulo = var_idModulo &&
            (
                IsBlank(cmbCKREAaeroporto_1.Selected.Result) ||
                Aeroporto = cmbCKREAaeroporto_1.Selected.Result
            )
        ),
        ID,
        SortOrder.Descending
    )
)

With(
    {
        varBuscaCKREA: Trim(txtBuscarCKREA_3.Value)
    },
    Sort(
        Filter(
            col_checkListREA,

            (
                IsBlank(dtpCKREAdataIni_1.SelectedDate) ||
                Data >= dtpCKREAdataIni_1.SelectedDate
            ) &&

            (
                IsBlank(dtpCKREAdataFin_1.SelectedDate) ||
                Data < DateAdd(
                    dtpCKREAdataFin_1.SelectedDate,
                    1,
                    TimeUnit.Days
                )
            ) &&

            (
                IsBlank(cmbCKREAbloco_1.Selected.Value) ||
                StartsWith(
                    Bloco,
                    cmbCKREAbloco_1.Selected.Value
                )
            ) &&

            (
                IsBlank(cmbCKREAaeroporto_1.Selected.Result) ||
                StartsWith(
                    Aeroporto,
                    cmbCKREAaeroporto_1.Selected.Result
                )
            ) &&

            (
                IsBlank(varBuscaCKREA) ||
                StartsWith(
                    Text(ID),
                    varBuscaCKREA
                ) ||
                StartsWith(
                    Protocolo,
                    varBuscaCKREA
                )
            )
        ),
        Data,
        SortOrder.Descending
    )
)

UpdateContext(
    {
        var_visibleExcluirTesteContato: true,
        var_dadosTesteContatos: ThisItem
    }
);

Set(varExcluindoTesteContatos, false);
Set(varReativarContatosAoExcluirTeste, false);

Refresh(tbl_testeContatos);
Refresh(tbl_contatos_entidades);

ClearCollect(
    colTesteContatosExcluir,
    Filter(
        tbl_testeContatos,
        id_teste_base = ThisItem.ID &&
        aeroporto = ThisItem.Aeroporto
    )
);

ClearCollect(
    colContatosRollbackExcluir,
    Filter(
        AddColumns(
            Filter(
                tbl_contatos_entidades,
                Aeroporto = ThisItem.Aeroporto &&
                status = "Desatualizado"
            ) As CONTATO,

            qtdFalhasNesteTeste,
            CountRows(
                Filter(
                    colTesteContatosExcluir As TESTE,
                    TESTE.id_contato = CONTATO.ID &&
                    TESTE.status.Value = "Contato não Realizado"
                )
            ),

            houveRealizadoNesteTeste,
            !IsBlank(
                LookUp(
                    colTesteContatosExcluir As TESTE_REALIZADO,
                    TESTE_REALIZADO.id_contato = CONTATO.ID &&
                    TESTE_REALIZADO.status.Value = "Contato Realizado"
                )
            )
        ),

        qtdFalhasNesteTeste >= 3 &&
        !houveRealizadoNesteTeste
    )
)

Set(varTesteSelecionado, ThisItem);
Set(varTesteAtualID, ThisItem.ID);
Set(varAeroportoRelatorio, ThisItem.Aeroporto);
Set(varAeroportoTesteAtual, ThisItem.Aeroporto);

ClearCollect(
    colContatosAeroRelatorio,
    Filter(
        tbl_contatos_entidades,
        Aeroporto = varAeroportoRelatorio
    )
);

ClearCollect(
    colTestesRelatorio,
    Filter(
        tbl_testeContatos,
        id_teste_base = varTesteAtualID &&
        aeroporto = varAeroportoRelatorio
    )
);

UpdateContext(
    {
        var_visibleNovoTeste: true,
        var_relatorio: true,
        var_dadosTesteContato: ThisItem
    }
);

ViewForm(FormNovoTeste)

Set(varNovoTesteContato, false);
Set(varConfirmando, false);
Set(varFinalizandoTeste, false);

Set(
    varIATATeste,
    Coalesce(
        ThisItem.IATA,
        LookUp(
            colAeros,
            Aeroporto = ThisItem.Aeroporto,
            IATA
        ),
        varIATAUser,
        Left(
            ThisItem.Aeroporto,
            3
        )
    )
);

Set(
    varTesteSelecionado,
    If(
        IsBlank(ThisItem.Protocolo),

        Patch(
            tbl_Checklist_REA_base,
            LookUp(
                tbl_Checklist_REA_base,
                ID = ThisItem.ID
            ),
            {
                Protocolo: varIATATeste & "-TES-CONT-" & Text(ThisItem.ID),
                IATA: varIATATeste
            }
        ),

        ThisItem
    )
);

Set(varTesteAtualID, varTesteSelecionado.ID);
Set(varAeroportoTesteAtual, varTesteSelecionado.Aeroporto);

UpdateContext(
    {
        var_visibleNovoTeste: true,
        var_relatorio: false,
        var_dadosTesteContato: varTesteSelecionado
    }
);

ClearCollect(
    colContatosAero,
    Filter(
        tbl_contatos_entidades,
        status = "Atualizado" &&
        Aeroporto = varAeroportoTesteAtual
    )
);

ClearCollect(
    colTestesExecucao,
    Filter(
        tbl_testeContatos,
        id_teste_base = varTesteAtualID &&
        aeroporto = varAeroportoTesteAtual
    )
);

EditForm(FormNovoTeste)

UpdateContext(
    {
        var_visibleNovoTeste: false,
        var_relatorio: false,
        var_dadosTesteContato: Blank()
    }
);

Set(varTesteAtualID, Blank());
Set(varTesteSelecionado, Blank());
Set(varConfirmando, false);
Set(varFinalizandoTeste, false);

ResetForm(FormNovoTeste);

Clear(colTestesExecucao);
Clear(colTestesRelatorio);
Clear(colContatosDesatualizadosEmail)

Set(
    varTesteSelecionado,
    Patch(
        tbl_Checklist_REA_base,
        FormNovoTeste.LastSubmit,
        {
            Protocolo: Coalesce(
                FormNovoTeste.LastSubmit.Protocolo,
                varIATAUser & "-TES-CONT-" & FormNovoTeste.LastSubmit.ID
            ),
            Status: "Em andamento"
        }
    )
);

Set(varTesteAtualID, varTesteSelecionado.ID);
Set(varAeroportoTesteAtual, varTesteSelecionado.Aeroporto);

UpdateContext(
    {
        var_visibleNovoTeste: true,
        var_relatorio: false,
        var_dadosTesteContato: varTesteSelecionado
    }
);

ClearCollect(
    colContatosAero,
    Filter(
        tbl_contatos_entidades,
        status = "Atualizado" &&
        Aeroporto = varAeroportoTesteAtual
    )
);

ClearCollect(
    colTestesExecucao,
    Filter(
        tbl_testeContatos,
        id_teste_base = varTesteAtualID &&
        aeroporto = varAeroportoTesteAtual
    )
);

Notify(
    "Progresso salvo com sucesso. Agora registre os contatos.",
    NotificationType.Success,
    3000
);

Select(ButtonRefreshChekREAcontatos)

ControlPropertyState.AutoRuleBindingString:
UpdateContext(
    {
        var_visibleFormContatos: true,
        var_acaoFormContatos: "Editar contato",
        var_dadosContatos: ThisItem
    }
);
EditForm(FormCadastrarContato)

If(
    DataCardValue3_10.Selected.Value = "Contato Realizado" And IsBlank(DataCardValue4_4.Value),
    Notify(
        "Erro: O nome do contato é obrigatório!",
        NotificationType.Error
    ),
    Patch(
        tbl_testeContatos,
        Defaults(tbl_testeContatos),
        {
            id_contato: ThisItem.ID,
            status: DataCardValue3_10.Selected,
            nome_contato: DataCardValue4_4.Value,
            observacoes: DataCardValue4_2.Value
        }
    );
    If(
        CountRows(
            Filter(
                Sort(
                    tbl_testeContatos,
                    ID,
                    SortOrder.Descending
                ),
                Month(Criado) = Month(Today()) && Year(Criado) = Year(Today()),
                status.Value = "Contato não Realizado",
                id_contato = ThisItem.ID
            )
        ) = 3,
        Patch(
            tbl_contatos_entidades,
            ThisItem,
            {status: "Desatualizado"}
        )
    );
    Notify(
        "Teste realizado com sucesso!",
        NotificationType.Success
    );
    Reset(DataCardValue3_10);
    Reset(DataCardValue4_4);
    Reset(DataCardValue4_2)
)

Rules.InvariantScript:
UpdateContext(
    {
        var_visibleExcluirTesteContato: false,
        var_dadosTesteContatos: Blank()
    }
);

Set(varExcluindoTesteContatos, false);
Set(varReativarContatosAoExcluirTeste, false);

Clear(colTesteContatosExcluir);
Clear(colContatosRollbackExcluir)

If(
    IsBlank(var_dadosTesteContatos.ID),

    Notify(
        "Nenhum teste selecionado para exclusão.",
        NotificationType.Error,
        3000
    ),

    Set(varExcluindoTesteContatos, true);

    Refresh(tbl_testeContatos);
    Refresh(tbl_Checklist_REA_base);
    Refresh(tbl_contatos_entidades);

    ClearCollect(
        colTesteContatosExcluir,
        Filter(
            tbl_testeContatos,
            id_teste_base = var_dadosTesteContatos.ID &&
            aeroporto = var_dadosTesteContatos.Aeroporto
        )
    );

    ForAll(
        colTesteContatosExcluir As TESTE_EXCLUIR,

        RemoveIf(
            tbl_testeContatos,
            ID = TESTE_EXCLUIR.ID
        )
    );

    RemoveIf(
        tbl_Checklist_REA_base,
        ID = var_dadosTesteContatos.ID
    );

    Notify(
        "Teste excluído com sucesso. Registros de contatos testados removidos: " &
        Text(CountRows(colTesteContatosExcluir)) &
        ".",
        NotificationType.Success,
        5000
    );

    UpdateContext(
        {
            var_visibleExcluirTesteContato: false,
            var_visibleNovoTeste: false,
            var_relatorio: false,
            var_dadosTesteContato: Blank(),
            var_dadosTesteContatos: Blank()
        }
    );

    Set(varTesteAtualID, Blank());
    Set(varTesteSelecionado, Blank());
    Set(varAeroportoTesteAtual, Blank());
    Set(varExcluindoTesteContatos, false);
    Set(varReativarContatosAoExcluirTeste, false);

    Clear(colTesteContatosExcluir);
    Clear(colContatosRollbackExcluir);
    Clear(colTestesExecucao);
    Clear(colTestesRelatorio);

    Select(ButtonRefreshChekREAcontatos)
)

ControlPropertyState.AutoRuleBindingString:
Patch(
    tbl_contatos_entidades_log,
    Defaults(tbl_contatos_entidades_log),
    {
        id_contato: var_dadosContatos.ID,
        aeroporto: var_dadosContatos.Aeroporto,
        bloco: var_dadosContatos.Bloco,
        acao: "Exclusão",
        origem: "Gestão de Contatos",
        nome_contato: var_dadosContatos.nome,
        status_anterior: var_dadosContatos.status,
        status_novo: "Excluído",
        usuario_nome: User().FullName,
        usuario_email: User().Email,
        detalhes: "Contato excluído pela gestão de contatos.",
        DetalhesHtml:
            "<div style='font-family:Segoe UI, Arial, sans-serif; font-size:12px; color:#b42318;'>
                Contato excluído pela gestão de contatos.
            </div>"
    }
);

RemoveIf(
    tbl_contatos_entidades,
    ID = var_dadosContatos.ID
);

UpdateContext(
    {
        var_visibleExcluirContato: false,
        var_dadosContatos: Blank()
    }
);

Notify(
    "Contato excluído com registro de histórico.",
    NotificationType.Warning,
    4000
);

Select(ButtonRefreshChekREAcontatos_2)
